def meta(s): return f'<div class="meta"><a href="author.html?name={s["author"].replace(" ","%20")}">{s["author"]}</a><span>·</span><span>{s["time"]}</span></div>'
def card(s): return f'<article class="card" data-category="{s["category"]}"><a class="image-link" href="{url(s)}">{img(s)}</a><a class="eyebrow accent" href="archive.html?category={s["category"]}">{s["category"]} <span>—</span> {s["section"]}</a><h3><a href="{url(s)}">{s["title"]}</a></h3>{meta(s)}</article>'
def row(s,n): return f'<article class="story-row"><span class="number">0{n}</span><div><a class="eyebrow accent" href="archive.html?category={s["category"]}">{s["category"]}</a><h3><a href="{url(s)}">{s["title"]}</a></h3>{meta(s)}</div><a href="{url(s)}">{img(s)}</a></article>'
def section_head(title,link='archive.html',label='View all stories'): return f'<div class="section-head"><h2>{title}</h2><a class="text-link" href="{link}">{label}<span aria-hidden="true">↗</span></a></div>'
